// Normalise/clean each entry's text before chunking + embedding
return $input.all().map((item) => {
  const raw = String(item.json.content || '');
  const cleaned = raw
    .replace(/\r\n/g, ' ')
    .replace(/[\u0000-\u001F\u007F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return {
    json: {
      ...item.json,
      content: cleaned,
      char_count: cleaned.length,
    },
  };
});
